begin;
select plan(10);
insert into auth.users(id) values ('66666666-6666-6666-6666-666666666666'),('77777777-7777-7777-7777-777777777777');
set local role service_role;
select lives_ok($$select public.billing_begin_intent('cccccccc-cccc-cccc-cccc-cccccccccccc','66666666-6666-6666-6666-666666666666','price_fixture',false)$$,'create server intent');
select lives_ok($$select public.billing_begin_intent('cccccccc-cccc-cccc-cccc-cccccccccccc','66666666-6666-6666-6666-666666666666','price_fixture',false)$$,'retry same intent');
select throws_ok($$select public.billing_begin_intent('cccccccc-cccc-cccc-cccc-cccccccccccc','77777777-7777-7777-7777-777777777777','price_fixture',false)$$,'P0001','Checkout request mismatch','cannot reuse another owner intent');
select lives_ok($$select public.billing_bind_intent('cccccccc-cccc-cccc-cccc-cccccccccccc','66666666-6666-6666-6666-666666666666','cs_intent_fixture')$$,'bind trusted provider session');
select throws_ok($$select public.billing_bind_intent('cccccccc-cccc-cccc-cccc-cccccccccccc','66666666-6666-6666-6666-666666666666','cs_other')$$,'P0001','Checkout already bound','binding immutable');
select is((public.billing_lookup_checkout('cs_intent_fixture')).owner_id,'66666666-6666-6666-6666-666666666666'::uuid,'trusted lookup uses saved owner');
select is((public.billing_lookup_checkout('cs_intent_fixture')).expected_amount,1999::bigint,'trusted checkout records the exact US$19.99 amount');
reset role;
update public.billing_intents set created_at=now()-interval '24 hours';
set local role service_role;
select throws_ok($$select public.billing_begin_intent('cccccccc-cccc-cccc-cccc-cccccccccccc','66666666-6666-6666-6666-666666666666','price_fixture',false)$$,'P0001','Checkout request expired','request cannot recreate Stripe session after idempotency expiry');
set local role authenticated;
select throws_ok($$select public.billing_begin_intent('dddddddd-dddd-dddd-dddd-dddddddddddd','66666666-6666-6666-6666-666666666666','price_fixture',false)$$,'42501','permission denied for function billing_begin_intent','browser cannot create trusted intent');
select throws_ok($$select public.billing_lookup_checkout('cs_intent_fixture')$$,'42501','permission denied for function billing_lookup_checkout','browser cannot inspect checkout owners');
reset role;
select * from finish();
rollback;
